const item = items[0];

if (
  !item.binary ||
  !item.binary.image1 ||
  !item.binary.image2 ||
  !item.binary.image3
) {
  throw new Error('Missing binary images (expected image1, image2, image3)');
}

return [
  {
    json: { imageNumber: 1 },
    binary: { image: item.binary.image1 }
  },
  {
    json: { imageNumber: 2 },
    binary: { image: item.binary.image2 }
  },
  {
    json: { imageNumber: 3 },
    binary: { image: item.binary.image3 }
  }
];

function extractOpenAIText(it) {
  // Merge by position may nest inputs under "0" or merge fields at top level
  const candidates = [it.json?.["0"], it.json].filter(Boolean);
  for (const o of candidates) {
    if (o?.content && Array.isArray(o.content)) {
      const t = o.content.map(x => x?.text).filter(Boolean).join("\n");
      if (t) return t;
    }
    if (typeof o?.text === "string" && o.text.trim()) return o.text.trim();
  }
  return null;
}

function extractDriveUrl(it) {
  return it.json?.webContentLink || it.json?.["1"]?.webContentLink
    || it.json?.webViewLink || it.json?.["1"]?.webViewLink || null;
}

const rows = items.map((it, idx) => ({
  n: idx + 1,
  desc: extractOpenAIText(it) || "No description",
  url: extractDriveUrl(it) || "No link",
}));

return [{
  json: {
    image1Description: rows[0]?.desc || "No description",
    image2Description: rows[1]?.desc || "No description",
    image3Description: rows[2]?.desc || "No description",

    image1Url: rows[0]?.url || "No link",
    image2Url: rows[1]?.url || "No link",
    image3Url: rows[2]?.url || "No link",
    imageUrls: rows.map(r => r.url).filter(u => u && u !== "No link"),

    allDescriptions: rows.map(r => `Image ${r.n}: ${r.desc}`).join("\n\n"),
  }
}];

const clip1 = $('Post Frames to Video API 1').first().json;
const clip2 = $('Post Frames to Video API 2').first().json;
const url1 = (clip1 && clip1.video && clip1.video.url) || null;
const url2 = (clip2 && clip2.video && clip2.video.url) || null;
const urls = [url1, url2].filter(Boolean);
if (urls.length < 2) {
  throw new Error('Expected two rendered clips but only found ' + urls.length);
}
return [{ json: { video_1: url1, video_2: url2, video_urls: urls } }];
